  "1d": {
    "point_estimate": 87.80,
    "90_ci": [83.50, 92.10]
  },
  "1w": {
    "point_estimate": 88.50,
    "90_ci": [80.00, 97.00]
  },
  "1m": {
    "point_estimate": 89.50,
    "90_ci": [73.00, 106.00]
  }
}

